-- V70：保留原有故事，追加适合六岁亲子共读的生活习惯与安全故事。
-- 每篇十二页独立插图、六道理解问答；大人承担照看责任，后果具体且不以羞辱或体罚呈现。

INSERT INTO unit (id, theme_id, name, sort_order, is_locked) VALUES
(157, 49, '蓝风车后面，妈妈不见了', 15, 0),
(158, 49, '红球滚过了白线', 16, 0),
(159, 49, '没能送出去的星星饼干', 17, 0),
(160, 49, '空了三格的小菜园', 18, 0);

INSERT INTO lesson (id, unit_id, name, type, content, sort_order, star_reward) VALUES
(627, 157, '蓝风车后面，妈妈不见了', 'READING', '{"type":"READING","items":[
  {"title":"约好一起看的魔术","content":"星期六，六岁的彭泽宇和妈妈去商场参加绘本魔术会。表演结束后，孩子们还能亲手做一只会转的纸鸟。他把报名卡放进口袋，一路猜纸鸟是不是会飞。进门时，妈妈带他认了服务台和书店收银台，约好一直待在彼此看得见的地方。彭泽宇答应得很快，眼睛却望向中庭：那里有一面蓝风车墙，每转一下，就像有许多小鱼游过去。","image":"habits-safety-six/blue-pinwheel-01"},
  {"title":"只过去看一眼","content":"妈妈在书店门口确认活动位置，彭泽宇站在她身边，踮脚看风车。一个小朋友走过去，用手轻轻一拨，蓝风车连着转了起来。他想自己只走几步，妈妈一抬头就能看见。没有说一声，也没有等妈妈回答，他便绕过摆书的小桌，走到了风车墙的另一面。那里的风车更大。他又往前挪了几步，把刚才的约定忘在了书店门口。","image":"habits-safety-six/blue-pinwheel-02"},
  {"title":"相同的围巾，不同的人","content":"等他看够了，转身却找不到妈妈。来来往往的人挡住了书店，他看见一条和妈妈一样的浅色围巾，赶紧跟了两步。那个人回头，是一张陌生的脸。彭泽宇连忙停住，手心一下湿了。刚才他很确定书店在左边，现在两条走廊看起来都很像。他的第一反应是跑回入口，心里又冒出妈妈说过的话：如果走散，先停下来，别越找越远。","image":"habits-safety-six/blue-pinwheel-03"},
  {"title":"先把脚步停下来","content":"他退到旁边不挡路的书店门边，远离扶梯和出入口，叫了几声妈妈。没有回应，他的眼泪快掉下来了。这时，一位路人问他是不是找不到家人，可以陪他出去看看。彭泽宇摇头说：我不出去，我要找这里的工作人员。路人没有生气，帮他招呼了几步之外的收银员。彭泽宇留在店门边，没有继续追着人影跑，也没有跟着任何人离开商场。","image":"habits-safety-six/blue-pinwheel-04"},
  {"title":"声音小，也要说明白","content":"收银员走过来蹲下，问他需要什么帮助。彭泽宇小声说出了自己的名字，又告诉她刚才和妈妈在这家书店门口。他本来想忍着不哭，可一张口还是哽咽了。收银员说可以慢慢讲，不用一个人去找。她叫来同事联系商场保安，自己陪他等在收银台旁的公开区域。彭泽宇看着来往的人，努力说出妈妈今天穿什么、背什么颜色的包，没有把重要的话都藏在眼泪里。","image":"habits-safety-six/blue-pinwheel-05"},
  {"title":"妈妈也在找他","content":"同一时间，妈妈发现身边没人，立刻叫他的名字，并请书店和商场工作人员帮忙寻找。她没有以为孩子只是贪玩，等他自己回来，而是说明最后看见他的位置，拿出手机里的近照。广播响起来的时候，彭泽宇坐在收银台旁，两只手紧紧抓着报名卡。短短一会儿，他觉得比等一整天都长。商场里还有许多笑声和音乐，他却只想听见妈妈回答一句：我在这里。","image":"habits-safety-six/blue-pinwheel-06"},
  {"title":"抱住以后还在发抖","content":"工作人员核对信息后，妈妈终于赶到了收银台。彭泽宇扑过去，哭得一句话也说不完整。妈妈抱住他，先确认他没有受伤，再一起坐下缓一缓。她说自己刚才也很害怕，不该让确认活动分散了照看他的注意。彭泽宇告诉她，自己没说就走开了，还差点跟着相同的围巾去了别处。两个人都没有把重逢变成一场责骂，也没有假装刚才什么都没发生。","image":"habits-safety-six/blue-pinwheel-07"},
  {"title":"纸鸟已经发完了","content":"等两个人都平静下来，魔术会已经结束。报名卡还在，制作纸鸟的材料却已经按人数分完。工作人员很抱歉，但不能把结束的活动重新开始。彭泽宇望着别的孩子举着纸鸟经过，心里空了一块。妈妈没有再去买一件礼物盖住他的难过，而是陪他坐着，看纸鸟一只只转过转角。今天损失的不只是做手工的机会，还有那段原本可以安心相伴、却用来焦急寻找的时间。","image":"habits-safety-six/blue-pinwheel-08"},
  {"title":"把约定说到能做到","content":"回家后，妈妈没有要求他保证永远不走散，而是和他练了三个动作：想离开身边，先说清要去哪里，等到回应；人多时牵好手；发现看不见家人，停在附近安全处并向工作人员求助。他练着说：我和家人走散了，请帮我联系他们。妈妈也把以后询问和付款时怎样牵着他想了一遍。约定不再只是一句要听话，而是他们两个人都知道下一步该做什么。","image":"habits-safety-six/blue-pinwheel-09"},
  {"title":"蓝风车又转起来了","content":"下一次去商场，风车墙还在。彭泽宇走到书店门口，又听见风车轻轻碰撞的声音。他抬头问：妈妈，我们一起过去看一会儿吗？妈妈先把手里的事情做完，再牵着他走过去。风车没有因为多等一会儿就停止转动。这一次，他能伸手拨一拨，也能回头看见妈妈。他忽然发现，先说一声并没有把喜欢的事拿走，只是让他们能一起安心地做。","image":"habits-safety-six/blue-pinwheel-10"},
  {"title":"帮忙，不是带着乱找","content":"他们准备离开时，看见一个小女孩站在玩具店门口哭。彭泽宇没有拉着她去找出口，也没有说自己带她找妈妈。他马上告诉身边的妈妈，请妈妈招呼店员。店员留在女孩身边，另一位工作人员去联系服务台。彭泽宇站在妈妈旁边，想起自己曾经攥紧的那张卡。他终于懂得，有些帮助不是赶紧带人跑起来，而是让人停在安全、能被找到的地方，等合适的大人来帮忙。","image":"habits-safety-six/blue-pinwheel-11"},
  {"title":"口袋里的那张旧卡","content":"那次没用上的报名卡，后来被彭泽宇夹进故事书里。纸鸟活动没有补回来，他再看到那张卡，仍会想起收银台旁漫长的等待。但下一次出门，他会主动看看身边的大人，也会问清要一起走哪条路。妈妈仍然认真照看他，不因为他学会几句话就让他单独逛商场。蓝风车会继续转，新的活动也会有。他最想带走的，是一整段不必互相寻找的快乐时光。","image":"habits-safety-six/blue-pinwheel-12"}
]}', 1, 3),

(628, 157, '走散与求助问答', 'QUIZ', '{"type":"QUIZ","items":[
  {"question":"彭泽宇和妈妈为什么会走散？","options":["他没说一声就绕到风车墙后，离开了彼此视线","蓝风车会把人吸走","妈妈让他独自去入口等"],"answer":0,"image":"habits-safety-six/blue-pinwheel-overview"},
  {"question":"发现找不到妈妈时，哪种做法更合适？","options":["独自去停车场找车","停在附近安全处，向店内工作人员求助","跟着衣服像妈妈的人一直走"],"answer":1,"image":"habits-safety-six/blue-pinwheel-overview"},
  {"question":"热心路人说陪他出去看看，他可以怎样回答？","options":["只要对方笑就跟着走","先走到商场外再决定","我不离开这里，请帮我叫工作人员"],"answer":2,"image":"habits-safety-six/blue-pinwheel-overview"},
  {"question":"找回妈妈以后，什么损失没有自动恢复？","options":["已经结束的魔术会和那段焦急寻找的时间","以后所有外出机会","和妈妈一起看书的能力"],"answer":0,"image":"habits-safety-six/blue-pinwheel-overview"},
  {"question":"后来想看风车时，他怎样做？","options":["先跑过去再喊妈妈","先说明想去哪里，等回应后一起过去","躲在墙后给妈妈惊喜"],"answer":1,"image":"habits-safety-six/blue-pinwheel-overview"},
  {"question":"看见别的小朋友走散了，六岁的他应该怎样帮忙？","options":["独自带对方到处寻找","把自己的家人留在原地","告诉身边的大人，请工作人员协助"],"answer":2,"image":"habits-safety-six/blue-pinwheel-overview"}
]}', 2, 3),

(629, 158, '红球滚过了白线', 'READING', '{"type":"READING","items":[
  {"title":"等了很久的接力游戏","content":"彭泽宇和乐乐约好，星期天下午在公园球场练双人运球。乐乐带来一只红球，球面上有他们自己画的小闪电，这是两个人上次活动一起赢到的。他们打算先练十次，再给等在终点的奶奶表演。爸爸来接时，先让他们把球放进网袋，说去球场的路上不拍球。彭泽宇抱了一会儿，又觉得球轻轻弹两下应该没关系。他太想让今天快一点开始了。","image":"habits-safety-six/red-ball-01"},
  {"title":"人行道不是球场","content":"走到靠近路口的人行道，彭泽宇把红球拿出来拍了一下。爸爸立即请他收好，他却想再拍一下就停。球这次碰到一块不平的砖，斜着弹了出去。乐乐伸手没有接住，红球沿着路边滚向前方。两个人都愣了一瞬。彭泽宇的眼睛只盯着红色，脚已经想往前迈，仿佛追上它比听见身边的声音更重要。爸爸赶紧牵住他，让两个孩子停在离路缘有距离的地方。","image":"habits-safety-six/red-ball-02"},
  {"title":"白线外的那一声","content":"红球滚过路边的白线，进入车辆行驶的地方。彭泽宇刚说出球两个字，一辆经过的小汽车便把它压瘪了，车继续向前，红球留在原地。他和乐乐谁都没有再往前走。爸爸让他们站在自己身边，远离车道。彭泽宇望着刚才还会弹跳的红球，觉得腿软软的。他没有受伤，却第一次看清了：球场里的追逐和道路上的车辆，并不会因为自己着急，就自动停下来等他。","image":"habits-safety-six/red-ball-03"},
  {"title":"不能为了球再迈一步","content":"乐乐小声问，能不能等没有车的时候捡回来。爸爸告诉他们，球滚进道路，要停下并告诉大人，孩子不能自己过去拿；大人也不能为了东西冒险。他先带两个孩子退到附近的安全休息处，请在路口值守的工作人员判断怎样处理。彭泽宇双手空着，想起刚才自己没有注意过的转弯车辆。不是爸爸喊得大声就能让每辆车停住，也不是自己跑得快，就一定来得及躲开。","image":"habits-safety-six/red-ball-04"},
  {"title":"闪电图案也压皱了","content":"等工作人员确认能安全处理后，把破损的球带到他们面前。球已经漏气，闪电图案皱在一起，再怎么捏也不能弹起来。乐乐抱着它，低声说这是他们一起赢到的，不是一只随便拿来的球。彭泽宇想说自己又不是故意的，话到了嘴边却停下了。他确实没有想弄坏它，但擅自在人行道上拍球，把两个人的东西带进了危险。他向乐乐道歉，没有拿不是故意的当作不用负责的理由。","image":"habits-safety-six/red-ball-05"},
  {"title":"今天的接力没有开始","content":"到了球场，奶奶已经把水壶放在树荫下，等着看他们配合运球。可两个孩子都没有兴致立刻借别人的球再玩，乐乐还需要缓一缓。爸爸陪他们坐下来，说明经过。原来约好的接力表演没有开始，红球也不能修回原来的样子。彭泽宇眼里发酸，既心疼球，也害怕自己刚才差点做出的动作。奶奶把手放在他肩上，没有让他假装勇敢，说难过可以慢慢讲出来。","image":"habits-safety-six/red-ball-06"},
  {"title":"对不起以后还有什么","content":"回家后，彭泽宇和爸爸商量怎样赔偿，请乐乐和家人一起决定。他愿意拿出自己能支配的一部分零花钱，剩下的安排由家长讨论，不能随便拿家里的钱。他还提出，以后过马路前由自己提醒把球收进网袋。乐乐说可以一起挑一只新球，但不会马上不心疼旧球。彭泽宇点头，把旧红球放进纸盒。它是一段共同的回忆，新买的东西能够继续用，却不是把那一段损失擦掉。","image":"habits-safety-six/red-ball-07"},
  {"title":"绿灯还不是最后一步","content":"第二天，爸爸陪他走同一个路口，这次没有带球。站在安全的等候位置，爸爸请他看看信号灯，再观察左右来车和转弯车辆。绿灯亮了，仍有一辆车正在完成转弯，他们继续等待。等确认车辆停让、通行条件安全，爸爸才牵着他从斑马线稳稳走过去。彭泽宇发现，看到绿灯就冲出去，和看到红球就冲出去一样，都把后面该看的事情省掉了。","image":"habits-safety-six/red-ball-08"},
  {"title":"看得见车，车未必看见我","content":"走到停着的车辆旁边，彭泽宇问：如果我能看见车，司机就能看见我吗？爸爸指给他看，车身、树木和转角会挡住视线，司机也不一定注意到了他。彭泽宇没有被要求独自判断每辆车的速度，爸爸仍然牵着他，走到能看清道路的路口再过街。六岁的他可以学习观察，但学习并不等于已经能独自应付交通。他要做的，是先停住、跟好大人，把注意力留给正在走的路。","image":"habits-safety-six/red-ball-09"},
  {"title":"网袋里的一次等待","content":"一周后，两家人商量好，给孩子们准备了一只新球。出发去球场时，彭泽宇自己把球收进网袋，又确认袋口收好。经过那段不平的人行道，他还是很想试试新球弹得有多高，手已经碰到袋口。他看见路边经过的车，把手移回来，握住爸爸。乐乐问到了吗，他指向前面的球场说，等进到能打球的地方再拿出来。这次短短的等待，保住了后面一整个下午。","image":"habits-safety-six/red-ball-10"},
  {"title":"不用拼命追的球","content":"球场里，三个大人先确认场地没有车辆经过，孩子们才打开网袋。新球有一次弹远了，彭泽宇先看它滚到哪里，再在场内去捡，没有一听见落地声就不管方向往前冲。练到第十次，两个人终于把球稳稳交到终点。奶奶拍起手，彭泽宇笑得很开心。他并没有变成不爱跑跳的孩子，只是开始分清：有些地方可以痛快玩，有些地方必须先停下来。","image":"habits-safety-six/red-ball-11"},
  {"title":"纸盒里的提醒","content":"旧红球没有和新球混放。彭泽宇把它留在家里的纸盒中，闪电图案仍然皱着。他偶尔打开看一眼，就会想起路边那一瞬间，自己眼里只有球，差点忘了车。他知道这次没有受伤，是因为大人及时阻止，也有运气的成分，不能拿来证明下一次也没事。后来每次出门，他都会先把球装好。等爸爸伸出手，他也把手伸过去，让喜欢的游戏从安全到达以后开始。","image":"habits-safety-six/red-ball-12"}
]}', 1, 3),

(630, 158, '红球与道路问答', 'QUIZ', '{"type":"QUIZ","items":[
  {"question":"红球滚进车道后，孩子应该先做什么？","options":["趁球还没滚远赶快追","停住脚步，告诉身边的大人","看自己跑得够不够快"],"answer":1,"image":"habits-safety-six/red-ball-overview"},
  {"question":"这次没有受伤，能说明以后追球也安全吗？","options":["不能，及时阻止和这次的幸运不能保证下一次安全","能，只要球还是红色","能，只要对司机挥手"],"answer":0,"image":"habits-safety-six/red-ball-overview"},
  {"question":"行人绿灯亮起，但转弯车辆还没停让，应该怎样做？","options":["立即跑过斑马线","自己去拦住车","和大人继续等，确认安全再通过"],"answer":2,"image":"habits-safety-six/red-ball-overview"},
  {"question":"彭泽宇开始学习看车以后，还需要大人陪过马路吗？","options":["不需要，知道绿灯就够了","需要，六岁的他仍需要大人陪伴和照看","只有拿着球时才需要"],"answer":1,"image":"habits-safety-six/red-ball-overview"},
  {"question":"新球买好后，哪一件损失仍没有恢复？","options":["共同赢到的旧红球已经损坏，那次接力也错过了","以后所有球场都不能去了","奶奶再也不能看他们玩球"],"answer":0,"image":"habits-safety-six/red-ball-overview"},
  {"question":"去球场的路上，怎样做能减少球滚入道路的机会？","options":["尽量拍得低一点","让伙伴在路边帮忙接","收好球并跟着大人，到合适场地再玩"],"answer":2,"image":"habits-safety-six/red-ball-overview"}
]}', 2, 3),

(631, 159, '没能送出去的星星饼干', 'READING', '{"type":"READING","items":[
  {"title":"送给新同学的小星星","content":"班里来了新同学米米，总是不好意思加入游戏。彭泽宇和安安想在周末亲子活动中做一盒星星饼干，作为大家一起分享的小礼物。老师先和家长确认了活动中的食物安排、过敏情况和能不能分享，再请大家准备无字小卡片。彭泽宇负责压星星形状，安安负责装盒，烤箱由大人操作。他已经想好了，打开盒子时，要先请米米选她喜欢的那一颗。","image":"habits-safety-six/star-cookies-01"},
  {"title":"先帮花盆搬个家","content":"活动开始前，几个孩子在门口帮老师把小花盆搬到阳光下。彭泽宇摸了摸盆沿的湿土，还帮一只玩具小车挖出停车位。回来时，他的手指边缘沾着一点泥。他看见安安已经洗好手，担心星星模具被别人先拿走，便想从洗手池前直接绕过去。妈妈提醒做食物前要认真洗手。他点了头，却只把手在水下晃了一下，没有用肥皂，就急着去看桌上的面团。","image":"habits-safety-six/star-cookies-02"},
  {"title":"看起来没有泥了","content":"彭泽宇把手往裤子上蹭了蹭，觉得看不见泥就算干净。大人正在另一边分材料，他趁着面团刚放好，先用手按平，又从中间揪了一块。星星还没压出来，桌边的小车就掉到了地上。他捡起小车，顺手放回旁边，又去碰面团。动作都很快，他没有注意到指甲边留下的泥，也没有想到刚捡过地上东西的手需要重新清洁。他只关心第一颗星星是不是自己做的。","image":"habits-safety-six/star-cookies-03"},
  {"title":"面团里的一点黑色","content":"妈妈走过来检查准备情况，看见他指甲边的泥，又在刚揉过的面团里发现一点土色。她立即让他停下，把这份面团单独移开，没有继续分给其他孩子。彭泽宇说把黑点挑掉不就好了吗？妈妈解释，脏手碰过的不一定只有看得见的那一点，不能凭看上去还好就拿来给大家做食物。安安手里的盒子还没折完，彭泽宇面前的星星模具却已经被暂时收到了清洗托盘里。","image":"habits-safety-six/star-cookies-04"},
  {"title":"这一份不能继续用了","content":"妈妈核对后发现，彭泽宇已经揉过分给他们小组的整份面团。她按活动的食品卫生要求处理掉受污染的部分，并清洁接触过的器具和桌面。面粉、黄油，还有大家准备的时间，都不能因为重新洗一遍手就回来。彭泽宇望着空下来的桌面，心里一紧。他第一次发现，省掉的不是只有自己手上的一小步；手伸进共享的材料里，也会把后果带到同伴面前。","image":"habits-safety-six/star-cookies-05"},
  {"title":"没有赶上烤箱的那一盘","content":"活动材料按报名人数准备，备用材料不够重做他们整组的份量，烤箱时间也已经排满。老师让他们参与后面的清洁和包装学习，但今天不能再做出原本约好的那一盒。米米来到桌边，看见空盒子，轻声问小星星在哪里。彭泽宇很想说烤箱不够用，最后还是把自己没有认真洗手、又碰了小车的经过说了出来。米米点点头，盒子上的丝带仍垂着，里面却没有礼物。","image":"habits-safety-six/star-cookies-06"},
  {"title":"说清楚，再问怎样补救","content":"彭泽宇向安安道歉，说自己着急抢第一颗星星，让她准备的盒子没能装满。他没有要求安安立刻开心起来，而是问还能帮什么。安安请他把桌面整理好，再一起完成给米米的小卡片。妈妈也承认，儿童活动的清洁步骤需要成人确认，不能以为提醒过就一定完成。彭泽宇听见这句话，并没有把自己的部分推掉。他拿起清洁布，按大人的安排做安全的整理工作，热器具仍然由大人处理。","image":"habits-safety-six/star-cookies-07"},
  {"title":"洗手池边的慢动作","content":"离开前，妈妈陪他重新走了一遍洗手步骤：用流动清水湿手，打上肥皂，认真揉搓手心、手背、指缝和指甲周围至少二十秒，再冲净、擦干。彭泽宇一开始觉得二十秒很长，搓着搓着，才发现自己过去总漏掉拇指和指缝。擦干后，他没有再往裤子上抹。妈妈告诉他，手上有些脏东西看不见，所以不是看到泥才洗，也不能用看起来干净代替真的洗干净。","image":"habits-safety-six/star-cookies-08"},
  {"title":"刚洗过，也会重新变脏","content":"几天后，家里准备晚饭，彭泽宇洗好手，想帮妈妈摆洗净的餐具。小车突然从口袋掉到地上，他捡起来后，手已经伸向盘子，又停住了。他把玩具送回盒子，回到洗手池重新洗手。妈妈问怎么不说刚洗过就算了，他指了指地上的小车：洗过是刚才，现在我又碰了别的东西。他发现，卫生习惯不是完成一次就永久有效，而是在需要的时候，愿意再做一次。","image":"habits-safety-six/star-cookies-09"},
  {"title":"第二次从手开始","content":"下一个周末，家长确认好分享安排后，彭泽宇和安安在妈妈陪伴下重新做饼干。桌上先腾出干净的区域，玩具留在客厅，两个人依次洗手、擦干，再拿器具。压星星时，彭泽宇没有争第一颗。他等安安放好模具，一起把边角收整齐。妈妈负责将烤盘送进烤箱，孩子们在安全的地方准备盒子。这一次，星星慢慢出现的过程，让他觉得比抢在别人前面更踏实。","image":"habits-safety-six/star-cookies-10"},
  {"title":"盒子里多了一句话","content":"饼干凉透并由大人确认可以分享后，两个孩子把它们装进盒子。送给米米时，彭泽宇说上次的礼物没做好，对不起；这一盒是他们重新准备的。米米邀请他们一起坐下，三个人先去洗手，再回到桌边分享。彭泽宇没有把迟到的这一盒说成上次从来没有失败。第一次活动的材料和机会确实用掉了，但后来认真完成的每一步，让他们终于把想表达的友好送到了对方面前。","image":"habits-safety-six/star-cookies-11"},
  {"title":"先把小星星放下","content":"后来再参加亲子活动，彭泽宇看见新的小熊模具，仍然觉得特别好玩。有人叫他快来看，他已经跑到桌边，又看见门口刚搬过的花盆。他把伸出去的手收回来，先请大人帮忙确认清洁，再去认真洗手。模具没有长腿跑掉，朋友也愿意等他一会儿。水声停下时，他擦干双手，重新走向制作桌。这一次，他知道送给别人的礼物，是从自己还没碰到面团的时候开始准备的。","image":"habits-safety-six/star-cookies-12"}
]}', 1, 3),

(632, 159, '洗手与分享问答', 'QUIZ', '{"type":"QUIZ","items":[
  {"question":"第一次面团为什么不能继续给大家做饼干？","options":["星星形状太小","安安不喜欢丝带","脏手接触并揉过面团，不能只挑掉看得见的土点"],"answer":2,"image":"habits-safety-six/star-cookies-overview"},
  {"question":"做食物前怎样洗手更合适？","options":["用清水和肥皂，认真揉搓至少二十秒，再冲净擦干","用水晃一下就去抓面团","擦在裤子上，看不到泥就算干净"],"answer":0,"image":"habits-safety-six/star-cookies-overview"},
  {"question":"已经洗过手，又捡起地上的玩具，接触食物前怎么办？","options":["刚洗过就不用再洗","先收好玩具，重新清洁双手","让玩具碰一下面团就知道干不干净"],"answer":1,"image":"habits-safety-six/star-cookies-overview"},
  {"question":"孩子在烘焙活动中可以怎样参与？","options":["自己从热烤箱里取盘子","趁大人不注意先尝生面团","洗净手后做适龄桌面操作，让大人处理烤箱和热器具"],"answer":2,"image":"habits-safety-six/star-cookies-overview"},
  {"question":"重新做出饼干后，第一次浪费的材料和活动时间会回来吗？","options":["不会，新礼物能表达心意，但原来的损失仍然存在","会，盒子一装满就全部恢复","只要不告诉同学就算没有发生"],"answer":0,"image":"habits-safety-six/star-cookies-overview"},
  {"question":"妈妈说清洁步骤也需要成人确认，说明什么？","options":["孩子以后可以随便碰食物","孩子练习卫生习惯，大人也要监督和协助","只要大人在场就不用洗手"],"answer":1,"image":"habits-safety-six/star-cookies-overview"}
]}', 2, 3),

(633, 160, '空了三格的小菜园', 'READING', '{"type":"READING","items":[
  {"title":"六盆送给邻居的春天","content":"社区准备办植物分享日，彭泽宇、安安和乐乐一起种了六盆小菜苗。每个人画两张图形名牌，等苗长稳了，就送给愿意继续照顾它们的邻居。六只花盆住在彭泽宇家院子里，下面有一张画着六个空格的大纸板。苗还很小时，三个孩子天天蹲着看，连新叶子卷开的样子都觉得神奇。彭泽宇拍着胸口说，离活动还有两个星期，放在自己家，他一定照顾得特别好。","image":"habits-safety-six/little-garden-01"},
  {"title":"不是每天倒同样一杯水","content":"爸爸和他们一起确认这种菜苗的照顾办法，教孩子每天先观察土和叶子，再由大人判断是否需要浇水、怎样摆放。彭泽宇负责饭后叫爸爸一起看，并把实际做过的事画在记录卡上。刚开始，他记得很牢：拿小壶、去院子、看看叶子，再请大人检查。爸爸还提醒，不能觉得一盆干，便给所有花盆倒同样多的水。彭泽宇蹲下来望着六盆苗，第一次把它们当作各有需要的小生命。","image":"habits-safety-six/little-garden-02"},
  {"title":"新积木把任务盖住了","content":"过了几天，家里来了新积木。彭泽宇饭后常常一坐下就想搭完整座车站，院子里的记录卡渐渐被压到绘画纸下面。爸爸问今天看过菜苗没有，他说等这节车厢搭好就去。等车厢完成，又想补一条轨道。那天最后是爸爸想起来，带他去检查。彭泽宇觉得反正最后有人记得，自己晚一点也没什么。他没有注意到，照顾的约定正在慢慢变成等别人替自己想起来。","image":"habits-safety-six/little-garden-03"},
  {"title":"一句以为，谁都没确认","content":"后来爸爸出差几天，出发前提出让妈妈接手一起检查。妈妈忙着准备家里的事情，以为爸爸已经和孩子把安排说清，爸爸也以为妈妈知道具体怎么照看。彭泽宇听见大人谈过，便以为不用自己提醒了，没有再问。接下来几天他仍旧埋头搭积木，只从窗边看一眼。那几天太阳晒得久，靠外侧的三盆土很快变干，里面的三盆有些遮阴。六盆苗不再是同一个样子，却一直没有人凑近认真看。","image":"habits-safety-six/little-garden-04"},
  {"title":"抬不起来的叶子","content":"安安来送分享日的小卡片，一到院子就停住了。外侧三盆苗的叶子软软垂下，有的边缘已经枯了，盆里的土很干。她问这几天有没有一起检查，彭泽宇说自己以为妈妈会管。妈妈听到后立刻过来，查看植物情况，按需要处理，联系熟悉种植的邻居请教。彭泽宇拿起小壶想把水一次倒满，被妈妈拦住：先弄清楚，着急补很多，也不一定能把几天的缺失补回来。","image":"habits-safety-six/little-garden-05"},
  {"title":"三盆重新站起来，三盆没有","content":"经过大人照料，原本状态较好的三盆慢慢缓过来，外侧严重干枯的三盆却没能恢复。分享日前一天，邻居帮忙确认，其中的苗已经不能继续生长，不能把它们当作健康的小苗送出去。彭泽宇摸着自己画的小太阳名牌，手指停了很久。种子发芽、新叶展开，大家一起等了那么多天；现在即使重新播种，明天也长不出同样的菜苗。六格纸板上，有三格真的要空下来了。","image":"habits-safety-six/little-garden-06"},
  {"title":"没有把空格藏起来","content":"乐乐问能不能临时买三盆别的苗放上去，彭泽宇一开始很想答应，这样别人就看不出少了。妈妈说可以买新的来种，但不能把买来的说成他们照顾长大的这一批。三个孩子商量后，只带去健康的三盆，把空格留着，并说明这次照顾和交接出了问题。原本六位邻居都表示愿意领一盆，如今只能让其中三位等下一次。彭泽宇要亲口解释，为什么自己答应过的六盆，只剩下一半。","image":"habits-safety-six/little-garden-07"},
  {"title":"大人和孩子各自说清楚","content":"分享日结束后，爸爸回来和全家一起复盘。他承认自己没有把照顾方法和责任交接清楚，妈妈也说忙起来以后没有确认到位。彭泽宇说，自己答应提醒，却一直等别人主动想起，也没有把不明白的地方问清。没有人把六岁的他当成能独立解决全部问题的人，也没有人替他把自己的那一部分抹掉。他们决定下次让安排更小、更清楚，做完再确认，而不是每个人都只说我以为。","image":"habits-safety-six/little-garden-08"},
  {"title":"先照顾好眼前这一盆","content":"重新开始时，彭泽宇只负责一盆。每天晚饭后，他先叫妈妈一起到院子观察，再按大人的判断帮忙做能做的事，结束后才在记录卡上画一个小点。如果妈妈忙着，他就明确问什么时候一起去，而不是默认有人已经完成。记录卡挂到门边，积木放在另一个地方。他仍然会忘，可这回忘记后会如实留下空格，再和妈妈核实情况，没有为了让纸上好看，偷偷把小点补上。","image":"habits-safety-six/little-garden-09"},
  {"title":"交出去，也要听见回答","content":"周末他要和妈妈外出一天，彭泽宇提前告诉爸爸，那盆苗需要按原来的方法检查。他没有说完就跑，而是把花盆位置、最近的情况和记录卡一起指给爸爸看，问爸爸是否方便接手。爸爸回答可以，又把安排复述了一遍。出门前，他们确认小壶和记录卡放在哪里。彭泽宇终于听懂交接的意思：不是把一句话扔给空气，而是让接手的人清楚知道、愿意承担，也有办法把事情做完。","image":"habits-safety-six/little-garden-10"},
  {"title":"迟到的小绿叶","content":"新的种子慢慢长大，没有因为他这次认真就一下长高。彭泽宇等了许多天，才看到适合分享的小苗。得到同意后，他和伙伴把新的一盆送给上次没能领到的邻居，说这是重新种的，不是那三盆又活了。邻居很高兴，但原先的分享日已经过去，原来的苗也没有回来。彭泽宇看着对方把花盆放到合适的位置，心里轻了一点。他知道补救可以继续，却不能替代一开始认真照顾。","image":"habits-safety-six/little-garden-11"},
  {"title":"积木先等我一下","content":"傍晚，新的车站还差一座屋顶。彭泽宇听见晚饭结束后收碗的声音，手停了一下，先去找妈妈：我们该一起看看那盆苗了。院子里只有风吹叶子的轻响，没有掌声，也没有人给他贴小队长徽章。他认真观察完，再回去接着搭屋顶。桌角仍放着那张曾经空了三格的展示纸。他没有把空格涂成漂亮花纹，因为它提醒自己，照顾别人托付的事情，要在没有观众的时候也记得去做。","image":"habits-safety-six/little-garden-12"}
]}', 1, 3),

(634, 160, '照顾与交接问答', 'QUIZ', '{"type":"QUIZ","items":[
  {"question":"三盆菜苗为什么错过了及时照顾？","options":["苗不喜欢小太阳名牌","孩子拖延提醒，大人交接不清，又没有确认实际情况","所有菜苗都不能放在院子里"],"answer":1,"image":"habits-safety-six/little-garden-overview"},
  {"question":"发现苗严重缺水，可以立刻把所有花盆灌满吗？","options":["可以，水越多就一定好得越快","可以，今天的水能替代前几天所有照顾","不可以，先请大人检查，根据植物情况处理"],"answer":2,"image":"habits-safety-six/little-garden-overview"},
  {"question":"为什么分享时留着三格空位？","options":["如实说明原来的苗受损，不能用新买的冒充","为了让邻居不敢种植物","因为健康的小苗也全部不能送了"],"answer":0,"image":"habits-safety-six/little-garden-overview"},
  {"question":"大人出差前最缺少哪一步？","options":["给花盆换一种颜色","把具体照顾安排交接清楚，并确认有人接手","要求六岁孩子独自负责全部植物"],"answer":1,"image":"habits-safety-six/little-garden-overview"},
  {"question":"如果忘记做记录，应该怎样办？","options":["直接补一个小点，纸上好看就行","告诉别人自己一直都做了","如实说没确认，与大人核实情况，不伪造完成记录"],"answer":2,"image":"habits-safety-six/little-garden-overview"},
  {"question":"后来重新种出小苗，说明什么？","options":["可以继续补救，但原来枯掉的苗和错过的分享日不会恢复","认真一天就能让种子立刻长大","只要结尾成功，平时不检查也没关系"],"answer":0,"image":"habits-safety-six/little-garden-overview"}
]}', 2, 3);
